window.READING_TESTS[7]={"id": 7, "module": "reading", "vol": 9, "sections": [{"number": 1, "html": "<p class=\"subheading\"><b>Questions 1–5</b></p><p class=\"instruction\">Choose <b>TRUE</b> if the statement agrees with the information given in the text, choose <b>FALSE</b> if the statement contradicts the information, or choose <b>NOT GIVEN</b> if there is no information on this.</p><div data-render-choice=\"1\"></div><div data-render-choice=\"2\"></div><div data-render-choice=\"3\"></div><div data-render-choice=\"4\"></div><div data-render-choice=\"5\"></div>\n<p class=\"subheading\"><b>Questions 6–13</b></p><p class=\"instruction\">Complete the table below.</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> from the passage for each answer.</p><p class=\"\"><b>Japanese seaweed industry</b></p><p>•    was destroyed by pollution and <span class=\"qnum\">6</span><input class=\"gap\" data-q=\"6\" aria-label=\"Câu 6\" autocomplete=\"off\" spellcheck=\"false\"> in 1948•    recovered as a result of Kathleen Drew-Baker’s research into <span class=\"qnum\">7</span><input class=\"gap\" data-q=\"7\" aria-label=\"Câu 7\" autocomplete=\"off\" spellcheck=\"false\"> a seaweed species similar to nori</p><p><i><b>Seaweed farming in the USA</b></i>•    new methods have resulted in the type of seaweed called <span class=\"qnum\">8</span><input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\"> becoming a successful crop•    has provided an alternative source of income for <span class=\"qnum\">9</span><input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\"></p><p><i><b>Seaweed production in the future</b></i>•    may be used to minimise the harmful effects of various <span class=\"qnum\">10</span><input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\"> produced by different industries•    the cost of production and shortage of <span class=\"qnum\">11</span><input class=\"gap\" data-q=\"11\" aria-label=\"Câu 11\" autocomplete=\"off\" spellcheck=\"false\"> may be preventing growth of the industry in Europe•    could create very large numbers of new <span class=\"qnum\">12</span><input class=\"gap\" data-q=\"12\" aria-label=\"Câu 12\" autocomplete=\"off\" spellcheck=\"false\">•    could be used instead of oil to power a small percentage of <span class=\"qnum\">13</span><input class=\"gap\" data-q=\"13\" aria-label=\"Câu 13\" autocomplete=\"off\" spellcheck=\"false\"></p>"}, {"number": 2, "html": "<p class=\"subheading\"><b>Questions 14–18</b></p><p class=\"instruction\">Reading Passage 2 has seven paragraphs, <b>A-G</b>.</p><p class=\"instruction\"><i>Which paragraph contains the following information?</i></p><p class=\"instruction\">Choose the correct letter, <b>A-G</b>, in boxes <b>14-19</b>.</p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> A</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> B</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> C</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> D</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> E</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> F</button><button class=\"token\" draggable=\"true\" data-token=\"G\"><b>G</b> G</button></div><p class=\"matching-row\" data-drop=\"14\"><span class=\"qnum\">14</span>a difference of opinion about where a group of languages originated <select class=\"answer-select\" data-q=\"14\" aria-label=\"Câu 14\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"15\"><span class=\"qnum\">15</span>a reference to a mythological figure <select class=\"answer-select\" data-q=\"15\" aria-label=\"Câu 15\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"16\"><span class=\"qnum\">16</span>an expression of one person&#x27;s doubt about a particular method of analysing scientific data <select class=\"answer-select\" data-q=\"16\" aria-label=\"Câu 16\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"17\"><span class=\"qnum\">17</span>an explanation of how one particular Celtic language spread due to the movement of people <select class=\"answer-select\" data-q=\"17\" aria-label=\"Câu 17\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"18\"><span class=\"qnum\">18</span>the reason why some language experts distrust language trees <select class=\"answer-select\" data-q=\"18\" aria-label=\"Câu 18\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p>\n<p class=\"subheading\"><b>Questions 19–22</b></p><p class=\"instruction\">Look at the following statements (<b>Questions 19-22</b>) and the list of people below.</p><p class=\"instruction\">Match each statement with the correct researcher or researchers, A, B, C or D.</p><p class=\"instruction\">Choose the correct letter, <b>A</b>, <b>B</b>, <b>C </b>or <b>D</b>, in boxes <b>19-22</b>.</p><p class=\"instruction\"><i><b>NB  You may use any letter more than once.</b></i></p><p class=\"instruction\"><b>List of Researchers</b></p><p class=\"instruction\"><b>A     </b>Dr Peter Forster &amp; Dr Alfred Toth</p><p class=\"instruction\"><b>B</b>     Dr Merritt Ruhlen</p><p class=\"instruction\"><b>C</b>     Dr Colin Renfrew</p><p class=\"instruction\"><b>D</b>     Dr April McMahon</p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> Dr Peter Forster &amp; Dr Alfred Toth</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> Dr Merritt Ruhlen</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> Dr Colin Renfrew</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> Dr April McMahon</button></div><p class=\"matching-row\" data-drop=\"19\"><span class=\"qnum\">19</span>An approach commonly used in language research has too narrow a focus. <select class=\"answer-select\" data-q=\"19\" aria-label=\"Câu 19\"><option value=\"\">Chọn</option><option value=\"A\">A · Dr Peter Forster &amp; Dr Alfred Toth</option><option value=\"B\">B · Dr Merritt Ruhlen</option><option value=\"C\">C · Dr Colin Renfrew</option><option value=\"D\">D · Dr April McMahon</option></select></p><p class=\"matching-row\" data-drop=\"20\"><span class=\"qnum\">20</span>The number of people who use a language has an effect on the modifications the language undergoes. <select class=\"answer-select\" data-q=\"20\" aria-label=\"Câu 20\"><option value=\"\">Chọn</option><option value=\"A\">A · Dr Peter Forster &amp; Dr Alfred Toth</option><option value=\"B\">B · Dr Merritt Ruhlen</option><option value=\"C\">C · Dr Colin Renfrew</option><option value=\"D\">D · Dr April McMahon</option></select></p><p class=\"matching-row\" data-drop=\"21\"><span class=\"qnum\">21</span>The Celtic language has been a distinct language for longer than experts previously thought. <select class=\"answer-select\" data-q=\"21\" aria-label=\"Câu 21\"><option value=\"\">Chọn</option><option value=\"A\">A · Dr Peter Forster &amp; Dr Alfred Toth</option><option value=\"B\">B · Dr Merritt Ruhlen</option><option value=\"C\">C · Dr Colin Renfrew</option><option value=\"D\">D · Dr April McMahon</option></select></p><p class=\"matching-row\" data-drop=\"22\"><span class=\"qnum\">22</span>The use of one family of languages may have become more extensive due to farming practices. <select class=\"answer-select\" data-q=\"22\" aria-label=\"Câu 22\"><option value=\"\">Chọn</option><option value=\"A\">A · Dr Peter Forster &amp; Dr Alfred Toth</option><option value=\"B\">B · Dr Merritt Ruhlen</option><option value=\"C\">C · Dr Colin Renfrew</option><option value=\"D\">D · Dr April McMahon</option></select></p>\n<p class=\"subheading\"><b>Questions 23–26</b></p><p class=\"instruction\">Complete the sentence below.</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> from the passage for each answer.</p><p>The script on the bronze tablet discovered in Coligny in France was written in a form of Celtic called <span class=\"qnum\">23</span><input class=\"gap\" data-q=\"23\" aria-label=\"Câu 23\" autocomplete=\"off\" spellcheck=\"false\"></p><p>After the success of the Roman Empire in conquering many parts of Europe, <span class=\"qnum\">24</span><input class=\"gap\" data-q=\"24\" aria-label=\"Câu 24\" autocomplete=\"off\" spellcheck=\"false\"> and its related languages became the predominant languages.</p><p><span class=\"qnum\">25</span><input class=\"gap\" data-q=\"25\" aria-label=\"Câu 25\" autocomplete=\"off\" spellcheck=\"false\"> is known to have occurred among the various versions of the Gaelic language around 3200 BC.</p><p>For social reasons, developments in languages are <span class=\"qnum\">26</span><input class=\"gap\" data-q=\"26\" aria-label=\"Câu 26\" autocomplete=\"off\" spellcheck=\"false\"></p>"}, {"number": 3, "html": "<p class=\"subheading\"><b>Questions 27–32</b></p><p class=\"instruction\">Choose the correct answer.</p><div data-render-choice=\"27\"></div><div data-render-choice=\"28\"></div><div data-render-choice=\"29\"></div><div data-render-choice=\"30\"></div><div data-render-choice=\"31\"></div><div data-render-choice=\"32\"></div>\n<p class=\"subheading\"><b>Questions 33–35</b></p><p class=\"instruction\">Complete each sentence with the correct ending, <b>A-F</b>, below.</p><p class=\"\"><b>A consumers do not follow expected purchasing patterns.</b></p><p class=\"\"><b>B people will always buy products that are better than those they already own.</b></p><p class=\"\"><b>C the &quot;status quo bias&quot; is purely theoretical.</b></p><p class=\"\"><b>D consumers have their own idea of the value of a product.</b></p><p class=\"\"><b>E innovations require expensive marketing campaigns.</b></p><p class=\"\"><b>F &quot;loss aversion&quot; can be measured.</b></p><p>The theory of relative advantage is based on the assumption that <span class=\"inline-match\" data-drop=\"33\"><span class=\"qnum\">33</span><select class=\"answer-select\" data-q=\"33\" aria-label=\"Câu 33\"><option value=\"\">Chọn</option><option value=\"A\">A · consumers do not follow expected purchasing patterns.</option><option value=\"B\">B · people will always buy products that are better than those they already own.</option><option value=\"C\">C · the &quot;status quo bias&quot; is purely theoretical.</option><option value=\"D\">D · consumers have their own idea of the value of a product.</option><option value=\"E\">E · innovations require expensive marketing campaigns.</option><option value=\"F\">F · &quot;loss aversion&quot; can be measured.</option></select></span>The 2002 Nobel Prize for economics was awarded for a study that explained why <span class=\"inline-match\" data-drop=\"34\"><span class=\"qnum\">34</span><select class=\"answer-select\" data-q=\"34\" aria-label=\"Câu 34\"><option value=\"\">Chọn</option><option value=\"A\">A · consumers do not follow expected purchasing patterns.</option><option value=\"B\">B · people will always buy products that are better than those they already own.</option><option value=\"C\">C · the &quot;status quo bias&quot; is purely theoretical.</option><option value=\"D\">D · consumers have their own idea of the value of a product.</option><option value=\"E\">E · innovations require expensive marketing campaigns.</option><option value=\"F\">F · &quot;loss aversion&quot; can be measured.</option></select></span>According to the first characteristic described by Kahneman and Tversky, <span class=\"inline-match\" data-drop=\"35\"><span class=\"qnum\">35</span><select class=\"answer-select\" data-q=\"35\" aria-label=\"Câu 35\"><option value=\"\">Chọn</option><option value=\"A\">A · consumers do not follow expected purchasing patterns.</option><option value=\"B\">B · people will always buy products that are better than those they already own.</option><option value=\"C\">C · the &quot;status quo bias&quot; is purely theoretical.</option><option value=\"D\">D · consumers have their own idea of the value of a product.</option><option value=\"E\">E · innovations require expensive marketing campaigns.</option><option value=\"F\">F · &quot;loss aversion&quot; can be measured.</option></select></span></p>\n<p class=\"subheading\"><b>Questions 36–40</b></p><p class=\"instruction\">Choose <b>YES</b> if the statement agrees with the claims of the writer, choose <b>NO</b> if the statement contradicts the claims of the writer, or <b>NOT GIVEN</b> if it is impossible to say what the writer thinks about this.</p><div data-render-choice=\"36\"></div><div data-render-choice=\"37\"></div><div data-render-choice=\"38\"></div><div data-render-choice=\"39\"></div><div data-render-choice=\"40\"></div><p class=\"\">PASSAGE 2 </p><p class=\"\">PASSAGE 3</p>"}], "passages": [{"number": 1, "title": "VOL 9 TEST 7", "subtitle": "<b>SEAWEED</b>"}, {"number": 2, "title": "THE HISTORY OF CELTIC LANGUAGE", "subtitle": ""}, {"number": 3, "title": "The psychology of new product adoptionJohn Gourville explores the reasons why consumers don't always buy new products.", "subtitle": ""}], "singles": [{"n": 1, "prompt": "Seaweed has been used to feed animals on some Scottish islands for thousands of years.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 2, "prompt": "In the 8th century in Japan, eating seaweed was reserved for special occasions.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 3, "prompt": "The findings at Monte Verde revealed new information about the significance of women’s roles in prehistoric times.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 4, "prompt": "Potash was Norway’s largest export in the 1800s.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 5, "prompt": "Dr Kathleen Drew-Banker is more famous in Japan than she is in the UK.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 27, "prompt": "In the first paragraph, what are we told about the current US marketplace?", "options": ["Almost half of all businesses that added new products collapse.", "Innovations in packaged goods have the greatest chance of success.", "It is a waste of money to invent new versions of products that already work well.", "The least successful companies are those that concentrate on existing products."]}, {"n": 28, "prompt": "In the second paragraph, what does the writer say about unsuccessful innovations?", "options": ["Companies should take advice from the experts.", "Innovations fail if companies lack business experience.", "The failure of many innovations can be predicted from the beginning.", "The reasons for product failure are more complex than is commonly thought."]}, {"n": 29, "prompt": "According to the characteristics described by Kahneman and Tversky, consumers", "options": ["compare new products with things they have bought previously.", "value new products more than ones they currently own.", "give up what they already have quite willingly.", "consider price more than any other factor."]}, {"n": 30, "prompt": "What are we told about the experiment conducted by Richard Thaler and his colleagues?", "options": ["The Choosers had to guess the correct price of the coffee mug.", "The Sellers valued their coffee mugs more than the Choosers did.", "The Sellers had to persuade the Choosers to buy their coffee mugs.", "The Choosers paid less money for their coffee mugs than the Sellers."]}, {"n": 31, "prompt": "In Jack Knetsch's demonstration, the second group of students were:", "options": ["given a choice of several different products at the beginning.", "asked to choose between what they had and a new product.", "allowed to keep both of the products they were shown.", "forced to give back the first product they had been given."]}, {"n": 32, "prompt": "What was the end result of Knetsch's demonstration?", "options": ["The majority of students reacted in a logical way.", "Most of the students preferred chocolate bars to coffee mugs.", "Almost all of the students were unwilling to swap their products.", "Half of the students with coffee mugs swapped them for chocolate bars."]}, {"n": 36, "prompt": "Everett Rogers' theory explains the psychology behind the choices consumers make.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 37, "prompt": "\"Loss aversion\" helps to explain why people fail to buy new products.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 38, "prompt": "Developers always believe their latest product will be a success.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 39, "prompt": "Developers waste too much time perfecting new products.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 40, "prompt": "A product champion is a person who develops a best-selling new product.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}], "pairs": [], "answers": {"1": ["TRUE"], "2": ["FALSE"], "3": ["TRUE"], "4": ["NOT GIVEN"], "5": ["TRUE"], "6": ["typhoons"], "7": ["laver"], "8": ["kelp"], "9": ["fishermen"], "10": ["chemicals"], "11": ["markets"], "12": ["jobs"], "13": ["vehicles"], "14": ["E"], "15": ["A"], "16": ["G"], "17": ["B"], "18": ["C"], "19": ["A"], "20": ["D"], "21": ["A"], "22": ["C"], "23": ["Gaulish"], "24": ["Latin"], "25": ["divergence"], "26": ["irregular"], "27": ["C"], "28": ["D"], "29": ["A"], "30": ["B"], "31": ["B"], "32": ["C"], "33": ["B"], "34": ["A"], "35": ["D"], "36": ["NO"], "37": ["YES"], "38": ["NOT GIVEN"], "39": ["NOT GIVEN"], "40": ["NO"]}, "explanations": {"1": "<p>1 T</p><p>Câu hỏi: <i>Seaweed has been used to feed animals on some Scottish islands for thousands of years.</i></p><p>(Rong biển đã được dùng để cho động vật ăn trên một số đảo của Scotland trong hàng nghìn năm.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: For example, it has supplemented the diet of sheep in the Orkneys, islands off the coast of Scotland, since Neolithic times, roughly 5000 years ago.</p><p>(Ví dụ, rong biển đã được bổ sung vào khẩu phần ăn của cừu ở quần đảo Orkney (ngoài khơi Scotland) từ thời kỳ đồ đá mới, khoảng 5.000 năm trước.)</p>", "2": "<p>2 F</p><p>Câu hỏi: <i>In the 8th century in Japan, eating seaweed was reserved for special occasions.</i></p><p>(Vào thế kỷ thứ 8 ở Nhật Bản, ăn rong biển chỉ dành cho những dịp đặc biệt.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In the early part of the 8th century in Japan, seaweed was already such a key part of people’s regular diet that legislation was introduced giving people the right to pay their taxes to the Emperor in the form of seaweed.</p><p>(Vào đầu thế kỷ thứ 8 ở Nhật Bản, rong biển đã là một phần quan trọng trong bữa ăn hằng ngày của người dân đến mức luật pháp cho phép họ nộp thuế cho Thiên hoàng bằng rong biển.)</p>", "3": "<p>3 T</p><p>Câu hỏi: <i>The findings at Monte Verde revealed new information about the significance of women’s roles in prehistoric times.</i></p><p>(Những phát hiện ở Monte Verde đã tiết lộ thông tin mới về tầm quan trọng của vai trò phụ nữ thời tiền sử.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: However, these findings suggest that women, known to be responsible for the gathering of plants such as seaweed, also played an important pait in the provision of food.</p><p>(Tuy nhiên, những phát hiện này cho thấy rằng phụ nữ, vốn chịu trách nhiệm thu hái các loại cây như rong biển, cũng đóng vai trò quan trọng trong việc cung cấp thức ăn.)</p><p>Giải thích: Trước đây người ta nghĩ chủ yếu dựa vào đàn ông săn bắn. Phát hiện mới cho thấy phụ nữ cũng quan trọng.</p>", "4": "<p>4 NG</p><p>Câu hỏi: <i>Potash was Norway’s largest export in the 1800s.</i></p><p>(Potash là mặt hàng xuất khẩu lớn nhất của Na Uy vào những năm 1800.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In 1800, Norway exported 1500 tonnes of potash.</p><p>Năm 1800, Na Uy xuất khẩu 1.500 tấn potash.</p><p>Giải thích: Bài chỉ nói có xuất khẩu potash. Không nói đây là mặt hàng lớn nhất → thiếu thông tin.</p>", "5": "<p>5 T</p><p>Câu hỏi: <i>Dr Kathleen Drew-Baker is more famous in Japan than she is in the UK.</i></p><p>(Tiến sĩ Kathleen Drew-Baker nổi tiếng ở Nhật hơn ở Anh.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Although hardly anyone has heard of Dr Drew-Baker in the UK, she is known as the ‘Mother of the Sea’ in Japan, and a statue of her can be found in the Japanese city of Osaka.</p><p>(Mặc dù hầu như không ai ở Anh biết đến bà Drew-Baker, nhưng ở Nhật bà được gọi là “Mẹ của biển cả”.)</p><p>Giải thích: UK: hầu như không ai biết</p><p>Nhật: rất nổi tiếng → rõ ràng nổi tiếng hơn ở Nhật.</p>", "6": "<p>6 typhoons</p><p>Câu hỏi: <i>was destroyed by pollution and ______ in 1948</i></p><p>(Đã bị phá hủy bởi ô nhiễm và ______ vào năm 1948.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In 1948, however, a series of typhoons combined with increased pollution in coastal waters led to a total collapse in Japanese production of nori</p><p>(Tuy nhiên vào năm 1948, một loạt cơn bão cùng với tình trạng ô nhiễm gia tăng ở vùng nước ven biển đã khiến ngành sản xuất nori của Nhật sụp đổ hoàn toàn.)</p>", "7": "<p>7 laver</p><p>Câu hỏi: <i>into ______ a seaweed species similar to nori</i></p><p>(về ______ một loài rong biển tương tự nori)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Based at Manchester University in the 1940s, she was studying a seaweed called laver, which is the Welsh equivalent of nori.</p><p>(Làm việc tại Đại học Manchester vào những năm 1940, bà đã nghiên cứu một loại rong biển gọi là laver – tên gọi tương đương với nori trong tiếng Wales.)</p>", "8": "<p>8 kelp</p><p>Câu hỏi: <i>the type of seaweed called ______ becoming a successful crop</i></p><p>(loại rong biển gọi là ______ đã trở thành cây trồng thành công)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In the United States, Professor Charles Yarish of the University of Connecticut should probably be called the ‘Father of the Sea’ for his work on kelp, a large brown seaweed.</p><p>(Tại Mỹ, Giáo sư Charles Yarish của Đại học Connecticut có lẽ nên được gọi là “Cha của biển cả” nhờ công trình nghiên cứu về kelp – một loại rong biển nâu lớn.)</p>", "9": "<p>9 fishermen</p><p>Câu hỏi: <i>has provided an alternative source of income for ______</i></p><p>(đã tạo ra nguồn thu nhập thay thế cho ______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Yarish has helped make it an economically viable crop for the New England fishermen whose livelihoods were threatened by a combination of overfishing, pollution, and warming waters</p><p>(Yarish đã giúp biến nó thành một loại cây trồng mang lại hiệu quả kinh tế cho những ngư dân ở New England – những người đang bị đe dọa sinh kế bởi việc đánh bắt quá mức, ô nhiễm và nước biển ấm lên.)</p>", "10": "<p>10 chemicals</p><p>Câu hỏi: <i>may be used to minimise the harmful effects of various ______</i></p><p>(có thể được dùng để giảm tác hại của nhiều ______ khác nhau)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Its ability to absorb a number of environmentally unfriendly chemicals discharged by farms, factories and wastewater treatment plants also makes it valuable as a means of reducing pollution</p><p>(Khả năng hấp thụ nhiều loại hóa chất có hại cho môi trường do các trang trại, nhà máy và các cơ sở xử lý nước thải thải ra cũng khiến rong biển trở nên có giá trị như một cách để giảm ô nhiễm.)</p>", "11": "<p>11 markets</p><p>Câu hỏi: <i>the cost of production and shortage of ______ may be preventing growth of the industry in Europe</i></p><p>(chi phí sản xuất và sự thiếu hụt ______ có thể đang cản trở sự phát triển ngành này ở châu Âu)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The main constraints on the development of seaweed farming in Europe have been the lack of markets and the relative expense of European production compared to Asian production.</p><p>(Những trở ngại chính đối với sự phát triển của nghề nuôi trồng rong biển ở châu Âu là thiếu thị trường tiêu thụ và chi phí sản xuất ở châu Âu cao hơn so với châu Á.)</p>", "12": "<p>12 jobs</p><p>Câu hỏi: <i>could create very large numbers of new ______</i></p><p>(có thể tạo ra số lượng rất lớn các ______ mới)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Hitting that 500 million mark would boost the world’s food supply by 10% from the current level, generating 50 million jobs in the process.</p><p>(Nếu đạt mốc 500 triệu đó, nguồn cung lương thực toàn cầu sẽ tăng thêm 10% so với hiện nay, đồng thời tạo ra khoảng 50 triệu việc làm.)</p>", "13": "<p>13 vehicles</p><p>Câu hỏi: <i>could be used instead of oil to power a small percentage of ______</i></p><p>(có thể được dùng thay dầu để vận hành một tỷ lệ nhỏ ______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: As a biofuel for vehicles, it could also replace about 1.5% of the fossil fuels used today.</p><p>(Làm nhiên liệu sinh học cho phương tiện giao thông, nó có thể thay thế khoảng 1,5% nhiên liệu hóa thạch hiện nay.)</p>", "14": "<p>14 E</p><p>Câu hỏi: <i>a difference of opinion about where a group of languages originated</i></p><p>(Sự khác biệt trong quan điểm về nơi bắt nguồn của một nhóm ngôn ngữ.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Specialists have long debated which country was the homeland of the Indo-Europeans and whether their language was spread by conquest or because its speakers were the first agriculturists whose methods and tongue were adopted by other populations.</p><p>(Các chuyên gia từ lâu đã tranh luận về việc quốc gia nào là quê hương của người Ấn-Âu, và liệu ngôn ngữ của họ được lan truyền nhờ chinh phục hay vì họ là những người làm nông nghiệp đầu tiên, nên phương thức canh tác và ngôn ngữ của họ đã được các cộng đồng khác tiếp nhận.)</p>", "15": "<p>15 A</p><p>Câu hỏi: <i>a reference to a mythological figure</i></p><p>(Một chỗ nhắc tới nhân vật thần thoại.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In November 1897, in a field near the village of Coligny in eastern France, a local inhabitant unearthed two strange objects. One was an imposing statue of Mars, the Roman god of war. </p><p>(Vào tháng 11 năm 1897, trên một cánh đồng gần làng Coligny ở miền đông nước Pháp, một người dân địa phương đã đào được hai vật thể kỳ lạ. Một trong số đó là bức tượng uy nghi của Mars – vị thần chiến tranh của La Mã.)</p>", "16": "<p>16 G</p><p>Câu hỏi: <i>an expression of one person&#x27;s doubt about a particular method of analysing scientific data</i></p><p>(Một người bày tỏ sự nghi ngờ về một phương pháp phân tích dữ liệu khoa học cụ thể.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: She had less confidence in the dating method, she said</p><p>(Bà cho biết mình ít tin tưởng hơn vào phương pháp xác định niên đại này.)</p>", "17": "<p>17 B</p><p>Câu hỏi:<i> an explanation of how one particular Celtic language spread due to the movement of people</i></p><p>(Giải thích việc một ngôn ngữ Celt cụ thể lan rộng do con người di cư.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In the British Isles, Celtic speakers survived in two main groups: the Goidelic branch of Celtic, which includes Irish and Scots Gaelic, and the Brythonic branch, formed mainly of Welsh and Breton, a Celtic tongue carried to Brittany in France by emigrants from Cornwall.</p><p>(Tại quần đảo Anh, những người nói tiếng Celt tồn tại trong hai nhóm chính: nhánh Goidelic gồm tiếng Ireland và tiếng Gaelic của Scotland; và nhánh Brythonic, chủ yếu gồm tiếng Wales và tiếng Breton – một ngôn ngữ Celt được những người di cư từ Cornwall mang tới vùng Brittany của Pháp.)</p>", "18": "<p>18 C</p><p>Câu hỏi: <i>the reason why some language experts distrust language trees</i></p><p>(Lý do vì sao một số chuyên gia ngôn ngữ không tin vào cây ngôn ngữ.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Because languages change so fast, historical linguists have little faith in language trees that go back more than a few thousand years.</p><p>(Vì ngôn ngữ thay đổi rất nhanh, các nhà ngôn ngữ học lịch sử ít tin tưởng vào những cây ngôn ngữ có niên đại kéo dài hơn vài nghìn năm.)</p>", "19": "<p>19 A</p><p>Câu hỏi: <i>An approach commonly used in language research has too narrow a focus.</i></p><p>(Một phương pháp thường dùng trong nghiên cứu ngôn ngữ có phạm vi quá hẹp.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Dr Forster and Dr Toth said their method of evaluating groups of languages against each other was similar to historical linguists, many of whom restrict their research to how words in only one single language have changed over time</p><p>(Tiến sĩ Forster và Tiến sĩ Toth cho biết phương pháp so sánh các nhóm ngôn ngữ của họ khá giống với phương pháp của các nhà ngôn ngữ học lịch sử, nhưng nhiều người trong số đó chỉ giới hạn nghiên cứu vào việc từ ngữ trong một ngôn ngữ duy nhất đã thay đổi theo thời gian như thế nào.)</p><p>=&gt; Đáp án: A Dr Peter Forster &amp; Dr Alfred Toth</p>", "20": "<p>20 D</p><p>Câu hỏi: <i>The number of people who use a language has an effect on the modifications the language undergoes.</i></p><p>(Số lượng người sử dụng một ngôn ngữ ảnh hưởng tới những thay đổi của ngôn ngữ đó.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: She had less confidence in the dating method, she said, because language changes in an irregular way based on social factors like the size of the speaker&#x27;s group and its degree of contact with others</p><p>(Bà cho biết mình ít tin tưởng hơn vào phương pháp xác định niên đại này vì ngôn ngữ thay đổi theo cách không đều, phụ thuộc vào các yếu tố xã hội như quy mô của cộng đồng người nói và mức độ tiếp xúc của họ với các nhóm khác.)</p><p>=&gt; Đáp án: D Dr April McMahon</p>", "21": "<p>21 A</p><p>Câu hỏi: <i>The Celtic language has been a distinct language for longer than experts previously thought.</i></p><p>(Tiếng Celt đã là một ngôn ngữ riêng biệt lâu hơn so với các chuyên gia từng nghĩ trước đây.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: They say that Celtic became a language in its own right and entered the British Isles much earlier than supposed.</p><p>(Họ cho rằng tiếng Celt đã trở thành một ngôn ngữ riêng biệt và du nhập vào quần đảo Anh sớm hơn nhiều so với giả định trước đây.)</p><p>=&gt; Đáp án: A Dr Peter Forster &amp; Dr Alfred Toth</p>", "22": "<p>22 C</p><p>Câu hỏi: <i>The use of one family of languages may have become more extensive due to farming practices.</i></p><p>(Một họ ngôn ngữ có thể đã lan rộng hơn nhờ hoạt động nông nghiệp.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The second theory, that it was spread by agriculture, has been advocated by archaeologist Dr Colin Renfrew. Dr Forster, who works with Dr Renfrew, said in an interview that the suggested date 8100 BC for the arrival of Indo-European in Europe does seem to vindicate Renfrew&#x27;s archaeological idea that the Indo-European languages were spread by farmers.</p><p>(Giả thuyết thứ hai – cho rằng ngôn ngữ này lan rộng nhờ nông nghiệp – đã được nhà khảo cổ học Tiến sĩ Colin Renfrew ủng hộ. Tiến sĩ Forster, người làm việc cùng ông Renfrew, cho biết trong một cuộc phỏng vấn rằng mốc thời gian khoảng năm 8100 TCN cho sự xuất hiện của ngôn ngữ Ấn-Âu ở châu Âu dường như đã củng cố quan điểm khảo cổ của Renfrew rằng các ngôn ngữ Ấn-Âu được lan truyền bởi những người nông dân.)</p><p>=&gt; Đáp án: C Dr Colin Renfrew</p>", "23": "<p>23 Gaulish</p><p>Câu hỏi:<i> The script on the bronze tablet discovered in Coligny in France was written in a form of Celtic called _______</i></p><p>(Phần chữ viết trên tấm bảng đồng được phát hiện ở Coligny (Pháp) được viết bằng một dạng tiếng Celt gọi là ________.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: It bore numerals in Roman but the words were in Gaulish, a version of the Celtic language spoken by the inhabitants of France before the Roman conquest in the first century BC.</p><p>(Trên đó có các chữ số La Mã, nhưng phần chữ viết lại bằng tiếng Gaulish – một dạng của tiếng Celt được cư dân Pháp sử dụng trước cuộc chinh phục của La Mã vào thế kỷ thứ nhất trước Công nguyên.)</p>", "24": "<p>24 Latin</p><p>Câu hỏi: <i>After the success of the Roman Empire in conquering many parts of Europe, _______and its related languages became the predominant languages.</i></p><p>(Sau khi Đế chế La Mã chinh phục nhiều vùng ở châu Âu thành công, ________ và các ngôn ngữ liên quan của nó trở thành những ngôn ngữ thống trị.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Then in the first century BC, the Romans defeated the Celts, both in France and in Britain, so decisively that their language, Latin, and its successor languages displaced Celtic over much of its former territory.</p><p>(Sau đó, vào thế kỷ thứ nhất trước Công nguyên, người La Mã đã đánh bại người Celt ở cả Pháp lẫn Anh một cách quyết định đến mức ngôn ngữ của họ là tiếng Latin cùng các ngôn ngữ phát triển từ nó đã thay thế tiếng Celt trên phần lớn lãnh thổ trước đây của người Celt.)</p>", "25": "<p>25 divergence</p><p>Câu hỏi: <i>______is known to have occurred among the various versions of the Gaelic language around 3200 BC.</i></p><p>(Người ta biết rằng đã xảy ra ________ giữa các dạng khác nhau của tiếng Gaelic vào khoảng năm 3200 TCN.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: They calculate that the Indo-European language initially fragmented in Europe around 8100 BC, plus or minus 1,900 years, and the divergence between the mainland European and British versions of Gaelic took place in 3200 BC, plus or minus 1,500 years.</p><p>(Họ tính toán rằng ngôn ngữ Ấn-Âu bắt đầu phân tách ở châu Âu vào khoảng năm 8100 TCN, sai số khoảng 1.900 năm; và sự phân hóa giữa tiếng Gaelic ở lục địa châu Âu với tiếng Gaelic tại Anh diễn ra vào khoảng năm 3200 TCN, sai số khoảng 1.500 năm.)</p>", "26": "<p>26 irregular</p><p>Câu hỏi: <i>For social reasons, developments in languages are______</i></p><p>(Vì các lý do xã hội, sự phát triển của ngôn ngữ là ________.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: She had less confidence in the dating method, she said, because language changes in an irregular way based on social factors like the size of the speaker&#x27;s group and its degree of contact with others.</p><p>(Bà cho biết mình ít tin tưởng hơn vào phương pháp xác định niên đại này vì ngôn ngữ biến đổi một cách không đều, chịu ảnh hưởng bởi các yếu tố xã hội như số lượng người nói trong cộng đồng và mức độ tiếp xúc của họ với những cộng đồng khác.)</p>", "27": "<p>27 C</p><p>Câu hỏi: <i>In the first paragraph, what are we told about the current US marketplace?</i>A.    Almost half of all businesses that added new products collapseB.    Innovations in packaged goods have the greatest chance of success.C.    It is a waste of money to invent new versions of products that already work well.D.    The least successful companies are those that concentrate on existing products.</p><p>(<i>Trong đoạn văn đầu tiên, chúng ta được biết điều gì về thị trường Mỹ hiện nay?</i>A.    Gần một nửa tất cả các doanh nghiệp tung ra sản phẩm mới bị phá sản.B.    Những đổi mới trong ngành hàng đóng gói có cơ hội thành công cao nhất.C.    Việc bỏ tiền để tạo ra những phiên bản mới của các sản phẩm vốn đã hoạt động tốt là lãng phí.D.    Những công ty kém thành công nhất là những công ty chỉ tập trung vào các sản phẩm hiện có.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: An American philosopher once said, &quot;If a man can ... make a better mousetrap than his neighbor ... the world will make a beaten path to his door. [...]However, businesses spend billions of dollars making better &quot;mousetraps&quot; only to find consumers rejecting them. </p><p>Một triết gia người Mỹ đã từng nói, “Nếu một người…có thể làm ra một cái bẫy chuột tốt hơn hàng xóm của anh ta…cả thế giới sẽ tạo thành con đường mòn tới cửa nhà anh ấy”.[...]Tuy nhiên, các doanh nghiệp tiêu tốn hàng tỷ đô la để làm ra “những cái bẫy chuột tốt hơn” chỉ để cho người tiêu dùng chối bỏ mà thôi.</p><p>Ở đây ngụ ý tác giả là cái bẫy chuột nó đã đủ tốt (work well) rồi, chế ra tốt hơn nữa người dùng cũng chẳng quan tâm.</p><p>Bẫy: According to one study, 47% of the start-up companies that pioneered new products later went out of business altogether.(Theo một nghiên cứu, 47% các công ty khởi nghiệp tiên phong tạo ra sản phẩm mới sau đó đã hoàn toàn phá sản.)Ở đây chỉ nói các cty khởi nghiệp tiên phong, không phải “all businesses”</p>", "28": "<p>28 D</p><p>Câu hỏi:<i> In the second paragraph, what does the writer say about unsuccessful innovations?</i>A.    Companies should take advice from the experts.B.    Innovations fail if companies lack business experience.C.    The failure of many innovations can be predicted from the beginning.D.    The reasons for product failure are more complex than is commonly thought.</p><p>(<i>Trong đoạn văn thứ hai, tác giả nói gì về những cải tiến mới không thành công?</i>A.    Các công ty nên nghe lời khuyên từ chuyên gia.B.    Những đổi mới thất bại vì công ty thiếu kinh nghiệm kinh doanh.C.    Sự thất bại của nhiều sản phẩm mới có thể được dự đoán ngay từ đầu.D.    Những lý do khiến sản phẩm thất bại phức tạp hơn so với điều mọi người thường nghĩ.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: To understand why new products fail we must delve into the psychology of behavior change</p><p>(Để hiểu vì sao các sản phẩm mới thất bại, chúng ta phải đi sâu vào tâm lý học của sự thay đổi hành vi.)</p>", "29": "<p>29 A</p><p>Câu hỏi: <i>According to the characteristics described by Kahneman and Tversky, consumers:</i>A.    compare new products with things they have bought previously.B.    value new products more than ones they currently own.C.    give up what they already have quite willingly.D.    consider price more than any other factor.</p><p>(<i>Theo những đặc điểm được Kahneman và Tversky mô tả, người tiêu dùng:</i>A.    so sánh sản phẩm mới với những thứ họ đã mua trước đó.B.    đánh giá sản phẩm mới cao hơn những sản phẩm họ đang sở hữu.C.    khá sẵn sàng từ bỏ những thứ mình đang có.D.    coi giá cả là yếu tố quan trọng hơn tất cả.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Second, consumers evaluate new products relative to the products they already own.</p><p>(Thứ hai, người tiêu dùng đánh giá các sản phẩm mới dựa trên sự so sánh với những sản phẩm mà họ đã sở hữu.)</p>", "30": "<p>30 B</p><p>Câu hỏi: <i>What are we told about the experiment conducted by Richard Thaler and his colleagues?</i>A.    The Choosers had to guess the correct price of the coffee mug.B.    The Sellers valued their coffee mugs more than the Choosers did.C.    The Sellers had to persuade the Choosers to buy their coffee mugs.D.    The Choosers paid less money for their coffee mugs than the Sellers.</p><p>(<i>Chúng ta biết điều gì về thí nghiệm do Richard Thaler và các đồng nghiệp thực hiện?</i>A.    Nhóm “người chọn” phải đoán mức giá chính xác của chiếc cốc cà phê.B.    Nhóm “người bán” đánh giá chiếc cốc cà phê của mình cao hơn nhóm “người chọn”.C.    Nhóm “người bán” phải thuyết phục nhóm “người chọn” mua chiếc cốc của họ.D.    Nhóm “người chọn” bỏ ra ít tiền hơn nhóm “người bán” để có được chiếc cốc cà phê.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Overall, the Sellers always demanded at least twice as much to give up the mugs as the Choosers would pay to obtain them.</p><p>(Nhìn chung, những người bán luôn đòi mức giá ít nhất cao gấp đôi số tiền mà những người chọn sẵn sàng trả để có được chiếc cốc.)</p>", "31": "<p>31 B</p><p>Câu hỏi: <i>In Jack Knetsch&#x27;s demonstration, the second group of students were:</i>A.    given a choice of several different products at the beginning.B.    asked to choose between what they had and a new product.C.    allowed to keep both of the products they were shown.D.    forced to give back the first product they had been given.</p><p>(<i>Trong thí nghiệm của Jack Knetsch, nhóm học sinh thứ hai:</i>A.    được chọn giữa nhiều sản phẩm khác nhau ngay từ đầu.B.    được yêu cầu chọn giữa món mình đang có và một sản phẩm mới.C.    được phép giữ cả hai món đồ được cho xem.D.    bị buộc phải trả lại món đồ đầu tiên được nhận.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: He gave a second group the coffee mugs but later allowed each student to exchange their mugs for a chocolate bar</p><p>(Ông đưa cốc cà phê cho nhóm thứ hai, nhưng sau đó cho phép mỗi học sinh đổi chiếc cốc của mình lấy một thanh sô-cô-la.)</p>", "32": "<p>32 C</p><p>Câu hỏi: <i>What was the end result of Knetsch&#x27;s demonstration?</i>A.    The majority of students reacted in a logical way.B.    Most of the students preferred chocolate bars to coffee mugs.C.    Almost all of the students were unwilling to swap their products.D.    Half of the students with coffee mugs swapped them for chocolate bars.</p><p>(<i>Kết quả cuối cùng của thí nghiệm của Knetsch là gì?</i>A.    Phần lớn học sinh phản ứng theo cách hợp lý.B.    Hầu hết học sinh thích thanh sô-cô-la hơn cốc cà phê.C.    Gần như tất cả học sinh đều không muốn đổi món đồ của mình.D.    Một nửa số học sinh có cốc cà phê đã đổi sang thanh sô-cô-la.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: However, in reality, only 11% of the students with mugs and 10% of those with chocolate bars wanted to exchange their products. To approximately 90% of the students, giving up what they already had seemed like a painful loss and reduced their desire to trade.</p><p>(Tuy nhiên, trên thực tế, chỉ có 11% số học sinh có cốc và 10% số học sinh có thanh sô-cô-la muốn đổi món đồ của mình. Với khoảng 90% học sinh, việc từ bỏ thứ mình đang có giống như một sự mất mát khó chịu, khiến họ ít muốn trao đổi hơn.)</p>", "33": "<p>33 B</p><p>Câu hỏi:<i> The theory of relative advantage is based on the assumption that</i></p><p>(Lý thuyết lợi thế tương đối dựa trên giả định rằng)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Companies have long assumed that they have only to develop innovations that are objectively superior to existing products, and consumers will have sufficient incentive to purchase them</p><p>(Từ lâu các công ty cho rằng họ chỉ cần phát triển những sản phẩm mới tốt hơn rõ ràng so với sản phẩm hiện có thì người tiêu dùng sẽ có đủ động lực để mua.)</p><p>Giải thích:  giả định là: sản phẩm tốt hơn thì người ta sẽ mua.</p><p>=&gt; Đáp án: B. people will always buy products that are better than those they already own. (Mọi người sẽ luôn mua sản phẩm tốt hơn những thứ họ đang có.)</p>", "34": "<p>34 A</p><p>Câu hỏi: <i>The 2002 Nobel Prize for economics was awarded for a study that explained why…</i></p><p>(Giải Nobel Kinh tế năm 2002 được trao cho nghiên cứu giải thích vì sao…)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In 2002, psychologist Daniel Kahneman won the Nobel Prize in economics for his research into the reasons why individuals deviate from rational economic behavior.</p><p>(Năm 2002, Daniel Kahneman nhận giải Nobel Kinh tế nhờ nghiên cứu về lý do tại sao con người không hành xử theo cách kinh tế hợp lý như dự đoán.)</p><p>Giải thích: người tiêu dùng không hành động đúng như mô hình dự đoán.</p><p>=&gt; Đáp án: A. consumers do not follow expected purchasing patterns. (người tiêu dùng không hành động đúng như mô hình dự đoán)</p>", "35": "<p>35 D</p><p>Câu hỏi: <i>According to the first characteristic described by Kahneman and Tversky…</i></p><p>(Theo đặc điểm đầu tiên mà Kahneman và Tversky mô tả…)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: First, people evaluate the attractiveness of an alternative based not on its objective or actual value, but on its subjective or perceived value.</p><p>(Thứ nhất, con người đánh giá sức hấp dẫn của một lựa chọn không dựa vào giá trị thực tế, mà dựa vào cách họ cảm nhận về giá trị đó.)</p><p>=&gt; Đáp án: D. consumers have their own idea of the value of a product. (Người tiêu dùng có quan điểm riêng về giá trị của một sản phẩm.)</p>", "36": "<p>36 No</p><p>Câu hỏi: <i>Everett Rogers&#x27; theory explains the psychology behind the choices consumers make.</i></p><p>(Lý thuyết của Everett Rogers giải thích tâm lý đứng sau những lựa chọn mà người tiêu dùng đưa ra.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Although compelling, the theory has one major flaw: it fails to capture the psychological biases that affect decision-making.</p><p>(Dù khá thuyết phục, lý thuyết này có một điểm hạn chế lớn: nó không giải thích được những thiên kiến tâm lý ảnh hưởng đến việc đưa ra quyết định.)</p>", "37": "<p>37 Y</p><p>Câu hỏi: <i>&quot;Loss aversion&quot; helps to explain why people fail to buy new products.</i></p><p>(“Sự né tránh mất mát” giúp giải thích vì sao mọi người không mua sản phẩm mới.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Loss aversion leads people to value products they already possess more than those that they don&#x27;t.</p><p>(Sự né tránh mất mát khiến con người coi trọng những sản phẩm mình đang sở hữu hơn những sản phẩm mà họ chưa có.)</p>", "38": "<p>38 NG</p><p>Câu hỏi: <i>Developers always believe their latest product will be a success.</i></p><p>(Các nhà phát triển luôn tin rằng sản phẩm mới nhất của họ sẽ thành công.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Having worked on a new product for years, developers operate in a world where their innovation is the reference point. They&#x27;re convinced that the product works and they are keenly aware of the shortcomings of existing alternatives. </p><p>Vì đã phát triển một sản phẩm mới nhiều năm liền, những nhà phát triển hoạt động trong một thế giới mà sự đột phá của họ là điểm tham chiếu. Họ bị thuyết phục rằng sản phẩm đó hoạt động tốt và nắm rõ những hạn chế của các đối thủ hiện tại.</p><p>Giải thích: Ở đây chỉ nói các nhà phát triển tin rằng sản phẩm của họ hoạt động tốt, không nhắc đến bán chạy hay không =&gt; NG</p>", "39": "<p>39 NG</p><p>Câu hỏi: <i>Developers waste too much time perfecting new products.</i></p><p>(Các nhà phát triển lãng phí quá nhiều thời gian để hoàn thiện sản phẩm mới.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: But developers are also biased - in favor of new products.</p><p>(Nhưng các nhà phát triển cũng có thiên kiến – họ thường nghiêng về phía các sản phẩm mới.)</p><p>Giải thích: Đoạn văn chỉ nói họ thiên vị sản phẩm mới, không nói gì về việc tốn quá nhiều thời gian hay lãng phí thời gian để hoàn thiện sản phẩm.</p>", "40": "<p>40 N</p><p>Câu hỏi: <i>A product champion is a person who develops a best-selling new product.</i></p><p>(Người tiên phong về sản phẩm là người phát triển ra sản phẩm mới bán chạy nhất.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: They&#x27;re convinced that the product works and they are keenly aware of the shortcomings of existing alternatives. Companies call those developers &quot;product champions&quot;</p><p>(Họ tin chắc rằng sản phẩm của mình hoạt động hiệu quả và cũng nhận thấy rất rõ những điểm hạn chế của các lựa chọn hiện có. Các công ty gọi những nhà phát triển đó là “người tiên phong về sản phẩm”.)</p><p>Giải thích: Không phải người tạo ra sản phẩm bán chạy nhất mà là người ủng hộ / thúc đẩy sản phẩm.</p>"}, "transcriptSegments": {"1": [{"id": "r1-p1", "text": "Seaweed, a common plant that grows in the sea, has been an important food, fuel, and fertilizer since prehistoric times. For example, it has supplemented the diet of sheep in the Orkneys, islands off the coast of Scotland, since Neolithic times, roughly 5000 years ago. In the early part of the 8th century in Japan, seaweed was already such a key part of people’s regular diet that legislation was introduced giving people the right to pay their taxes to the Emperor in the form of seaweed.", "html": "<p>Seaweed, a common plant that grows in the sea, has been an important food, fuel, and fertilizer since prehistoric times. For example, it has supplemented the diet of sheep in the Orkneys, islands off the coast of Scotland, since Neolithic times, roughly 5000 years ago. In the early part of the 8th century in Japan, seaweed was already such a key part of people’s regular diet that legislation was introduced giving people the right to pay their taxes to the Emperor in the form of seaweed.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p2", "text": "The oldest evidence of seaweed use was found in South America, dating from 12,500 years ago. The remains of red seaweed mixed with a medicinal herb were discovered on the floor of a medicine hut at Monte Verde, Chile, one of the oldest human habitation sites in the Americas. The Monte Verde findings led to a re-evaluation of the importance of plants to the communities of that region. It was previously believed that their diet was predominantly meat-based, and therefore reliant on the hunting skills of men. However, these findings suggest that women, known to be responsible for the gathering of plants such as seaweed, also played an important pait in the provision of food.", "html": "<p>The oldest evidence of seaweed use was found in South America, dating from 12,500 years ago. The remains of red seaweed mixed with a medicinal herb were discovered on the floor of a medicine hut at Monte Verde, Chile, one of the oldest human habitation sites in the Americas. The Monte Verde findings led to a re-evaluation of the importance of plants to the communities of that region. It was previously believed that their diet was predominantly meat-based, and therefore reliant on the hunting skills of men. However, these findings suggest that women, known to be responsible for the gathering of plants such as seaweed, also played an important pait in the provision of food.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p3", "text": "The first recorded commercial use of seaweed in Europe was in the 17th century in France and Norway. Coastal populations, mainly farmers, gathered and burnt seaweed to produce potash, a substance which is used in the production of glass and soap. In 1800, Norway exported 1500 tonnes of potash.", "html": "<p>The first recorded commercial use of seaweed in Europe was in the 17th century in France and Norway. Coastal populations, mainly farmers, gathered and burnt seaweed to produce potash, a substance which is used in the production of glass and soap. In 1800, Norway exported 1500 tonnes of potash.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p4", "text": "Simple seaweed cultivation techniques were first developed in Japan in the mid-17th century and became increasingly popular over the next three centuries. In 1948, however, a series of typhoons combined with increased pollution in coastal waters led to a total collapse in Japanese production of nori, the type of seaweed used to make sushi. And because almost nothing was known about its life cycle, no one could figure out how to grow new plants from scratch to repopulate the depleted seaweed beds. The country’s nori industry ground to a halt, and many farmers lost their livehoods. It was a British scientist, Dr. Kathleen Drew-Baker, who was credited with saving Japan’s seaweed farming industry. Based at Manchester University in the 1940s, she was studying a seaweed called laver, which is the Welsh equivalent of nori. In 1949, she published a paper outlining her discovery that certain tiny algae were actually baby seaweed, rather than an entirely separate species, as had previously been thought. After reading her research, Japanese scientists quickly developed methods for seeding these tiny algae artificially so that new plants could be grown. This made the mass production of nori possible. Although hardly anyone has heard of Dr Drew-Baker in the UK, she is known as the ‘Mother of the Sea’ in Japan, and a statue of her can be found in the Japanese city of Osaka.", "html": "<p>Simple seaweed cultivation techniques were first developed in Japan in the mid-17th century and became increasingly popular over the next three centuries. In 1948, however, a series of typhoons combined with increased pollution in coastal waters led to a total collapse in Japanese production of nori, the type of seaweed used to make sushi. And because almost nothing was known about its life cycle, no one could figure out how to grow new plants from scratch to repopulate the depleted seaweed beds. The country’s nori industry ground to a halt, and many farmers lost their livehoods. It was a British scientist, Dr. Kathleen Drew-Baker, who was credited with saving Japan’s seaweed farming industry. Based at Manchester University in the 1940s, she was studying a seaweed called laver, which is the Welsh equivalent of nori. In 1949, she published a paper outlining her discovery that certain tiny algae were actually baby seaweed, rather than an entirely separate species, as had previously been thought. After reading her research, Japanese scientists quickly developed methods for seeding these tiny algae artificially so that new plants could be grown. This made the mass production of nori possible. Although hardly anyone has heard of Dr Drew-Baker in the UK, she is known as the ‘Mother of the Sea’ in Japan, and a statue of her can be found in the Japanese city of Osaka.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p5", "text": "In the United States, Professor Charles Yarish of the University of Connecticut should probably be called the ‘Father of the Sea’ for his work on kelp, a large brown seaweed. The renowned scientist, who has been studying the biology of seaweed since the early 1970s, recently turned his attention to the development of revolutionary techniques for the harvesting of this species. Yarish has helped make it an economically viable crop for the New England fishermen whose livelihoods were threatened by a combination of overfishing, pollution, and warming waters.", "html": "<p>In the United States, Professor Charles Yarish of the University of Connecticut should probably be called the ‘Father of the Sea’ for his work on kelp, a large brown seaweed. The renowned scientist, who has been studying the biology of seaweed since the early 1970s, recently turned his attention to the development of revolutionary techniques for the harvesting of this species. Yarish has helped make it an economically viable crop for the New England fishermen whose livelihoods were threatened by a combination of overfishing, pollution, and warming waters.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p6", "text": "As the world population grows and the climate changes, there is increased interest from businesses and development organizations in the use of seaweed for food and energy. Seaweed, which can grow rapidly and efficiently, provides plant-based proteins, and could also be used as a source of biofuels to replace fossil fuels. Its ability to absorb a number of environmentally unfriendly chemicals discharged by farms, factories and wastewater treatment plants also makes it valuable as a means of reducing pollution.", "html": "<p>As the world population grows and the climate changes, there is increased interest from businesses and development organizations in the use of seaweed for food and energy. Seaweed, which can grow rapidly and efficiently, provides plant-based proteins, and could also be used as a source of biofuels to replace fossil fuels. Its ability to absorb a number of environmentally unfriendly chemicals discharged by farms, factories and wastewater treatment plants also makes it valuable as a means of reducing pollution.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p7", "text": "Seaweed cultivation in Asia has grown from the late 1950s into an industry offering sustainable employment in developing and emerging economies in many countries, notably Indonesia and China. However, seaweed farming is not very well developed in Europe and the industry still relies on the harvesting, either manually or mechanically, of wild seaweed. The main constraints on the development of seaweed farming in Europe have been the lack of markets and the relative expense of European production compared to Asian production.", "html": "<p>Seaweed cultivation in Asia has grown from the late 1950s into an industry offering sustainable employment in developing and emerging economies in many countries, notably Indonesia and China. However, seaweed farming is not very well developed in Europe and the industry still relies on the harvesting, either manually or mechanically, of wild seaweed. The main constraints on the development of seaweed farming in Europe have been the lack of markets and the relative expense of European production compared to Asian production.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p8", "text": "A 2016 report from the World Bank estimates that annual global seaweed production could reach 500 million dry tons by 2050 if the industry is able to increase its harvest by 14% per year. Hitting that 500 million mark would boost the world’s food supply by 10% from the current level, generating 50 million jobs in the process. As a biofuel for vehicles, it could also replace about 1.5% of the fossil fuels used today.", "html": "<p>A 2016 report from the World Bank estimates that annual global seaweed production could reach 500 million dry tons by 2050 if the industry is able to increase its harvest by 14% per year. Hitting that 500 million mark would boost the world’s food supply by 10% from the current level, generating 50 million jobs in the process. As a biofuel for vehicles, it could also replace about 1.5% of the fossil fuels used today.</p>", "letter": "A", "headingQuestion": null}], "2": [{"id": "r2-p1", "text": "A In November 1897, in a field near the village of Coligny in eastern France, a local inhabitant unearthed two strange objects. One was an imposing statue of Mars, the Roman god of war. The other was an ancient bronze tablet, 1.5 metres wide and 1 metre high. It bore numerals in Roman but the words were in Gaulish, a version of the Celtic language spoken by the inhabitants of France before the Roman conquest in the first century BC. The tablet turned out to be one of the most important sources of words from this extinct language.", "html": "<p><b>A</b> In November 1897, in a field near the village of Coligny in eastern France, a local inhabitant unearthed two strange objects. One was an imposing statue of Mars, the Roman god of war. The other was an ancient bronze tablet, 1.5 metres wide and 1 metre high. It bore numerals in Roman but the words were in Gaulish, a version of the Celtic language spoken by the inhabitants of France before the Roman conquest in the first century BC. The tablet turned out to be one of the most important sources of words from this extinct language.</p>", "letter": "A", "headingQuestion": null}, {"id": "r2-p2", "text": "B Two researchers, geneticist Dr Peter Forster and linguist Dr Alfred Toth, have now used the calendar and other Celtic inscriptions to reconstruct the history of Celtic and its position in the Indo-European family of languages. They say that Celtic became a language in its own right and entered the British Isles much earlier than supposed. Then in the first century BC, the Romans defeated the Celts, both in France and in Britain, so decisively that their language, Latin, and its successor languages displaced Celtic over much of its former territory. In the British Isles, Celtic speakers survived in two main groups: the Goidelic branch of Celtic, which includes Irish and Scots Gaelic, and the Brythonic branch, formed mainly of Welsh and Breton, a Celtic tongue carried to Brittany in France by emigrants from Cornwall.", "html": "<p><b>B </b>Two researchers, geneticist Dr Peter Forster and linguist Dr Alfred Toth, have now used the calendar and other Celtic inscriptions to reconstruct the history of Celtic and its position in the Indo-European family of languages. They say that Celtic became a language in its own right and entered the British Isles much earlier than supposed. Then in the first century BC, the Romans defeated the Celts, both in France and in Britain, so decisively that their language, Latin, and its successor languages displaced Celtic over much of its former territory. In the British Isles, Celtic speakers survived in two main groups: the Goidelic branch of Celtic, which includes Irish and Scots Gaelic, and the Brythonic branch, formed mainly of Welsh and Breton, a Celtic tongue carried to Brittany in France by emigrants from Cornwall.</p>", "letter": "B", "headingQuestion": null}, {"id": "r2-p3", "text": "C Because languages change so fast, historical linguists have little faith in language trees that go back more than a few thousand years. Dr Forster has developed a new dating method for relating a group of languages, basing it on the tree-drawing techniques used to trace the evolutionary relationships among genes. The method will work on just a handful of words, a fortunate circumstance since only some 30 Gaulish words have known counterparts in all the other languages under study. Dr Forster and Dr Toth have used the method to draw up a tree relating the different branches of Celtic to one another and to other Indo-European languages like English, French, Spanish, Latin and Greek. In a published article, they say that soon after the ancestral Indo-European language arrived in Europe over 5,000 years ago, it split into different branches leading to Celtic, Latin, Greek and English. Within Celtic, their tree shows that Gaulish the mainland European version of the language separated from its Goidelic and Brythonic cousins, much as might be expected from the facts of geography", "html": "<p><b>C</b> Because languages change so fast, historical linguists have little faith in language trees that go back more than a few thousand years. Dr Forster has developed a new dating method for relating a group of languages, basing it on the tree-drawing techniques used to trace the evolutionary relationships among genes. The method will work on just a handful of words, a fortunate circumstance since only some 30 Gaulish words have known counterparts in all the other languages under study. Dr Forster and Dr Toth have used the method to draw up a tree relating the different branches of Celtic to one another and to other Indo-European languages like English, French, Spanish, Latin and Greek. In a published article, they say that soon after the ancestral Indo-European language arrived in Europe over 5,000 years ago, it split into different branches leading to Celtic, Latin, Greek and English. Within Celtic, their tree shows that Gaulish the mainland European version of the language separated from its Goidelic and Brythonic cousins, much as might be expected from the facts of geography</p>", "letter": "C", "headingQuestion": null}, {"id": "r2-p4", "text": "D The researchers' method even dates the points at which their language tree divides, although the dates have a wide range of possibility. They calculate that the Indo-European language initially fragmented in Europe around 8100 BC, plus or minus 1,900 years, and the divergence between the mainland European and British versions of Gaelic took place in 3200 BC, plus or minus 1,500 years. These dates are much earlier than previously estimated. ‘The traditional date of the Indo-European fragmentation has been 4000 BC for some time,’ said linguist Dr Merritt Ruhlen. He said the new method ‘seems pretty reasonable’ and should be useful in tracing back the earlier history of the Indo-European language.", "html": "<p><b>D</b> The researchers&#x27; method even dates the points at which their language tree divides, although the dates have a wide range of possibility. They calculate that the Indo-European language initially fragmented in Europe around 8100 BC, plus or minus 1,900 years, and the divergence between the mainland European and British versions of Gaelic took place in 3200 BC, plus or minus 1,500 years. These dates are much earlier than previously estimated. ‘The traditional date of the Indo-European fragmentation has been 4000 BC for some time,’ said linguist Dr Merritt Ruhlen. He said the new method ‘seems pretty reasonable’ and should be useful in tracing back the earlier history of the Indo-European language.</p>", "letter": "D", "headingQuestion": null}, {"id": "r2-p5", "text": "E Specialists have long debated which country was the homeland of the Indo-Europeans and whether their language was spread by conquest or because its speakers were the first agriculturists whose methods and tongue were adopted by other populations. The second theory, that it was spread by agriculture, has been advocated by archaeologist Dr Colin Renfrew. Dr Forster, who works with Dr Renfrew, said in an interview that the suggested date 8100 BC for the arrival of Indo-European in Europe does seem to vindicate Renfrew's archaeological idea that the Indo-European languages were spread by farmers. Agriculture started to arrive in Europe from the Near East around 6000 BC, which is earlier than the traditional date proposed by linguists for the spread of Indo-European. This writing would fit with the lower end of Dr Forster's range of dates.", "html": "<p><b>E</b> Specialists have long debated which country was the homeland of the Indo-Europeans and whether their language was spread by conquest or because its speakers were the first agriculturists whose methods and tongue were adopted by other populations. The second theory, that it was spread by agriculture, has been advocated by archaeologist Dr Colin Renfrew. Dr Forster, who works with Dr Renfrew, said in an interview that the suggested date 8100 BC for the arrival of Indo-European in Europe does seem to vindicate Renfrew&#x27;s archaeological idea that the Indo-European languages were spread by farmers. Agriculture started to arrive in Europe from the Near East around 6000 BC, which is earlier than the traditional date proposed by linguists for the spread of Indo-European. This writing would fit with the lower end of Dr Forster&#x27;s range of dates.</p>", "letter": "E", "headingQuestion": null}, {"id": "r2-p6", "text": "F Dr Forster said that his estimated date of 3200 BC for the arrival of Celtic speakers in the British Isles is also much earlier than the usual date, 600 BC, posited on the basis of archaeological evidence. Dr Forster and Dr Toth said their method of evaluating groups of languages against each other was similar to historical linguists, many of whom restrict their research to how words in only one single language have changed over time. Asked what linguists thought of his approach he said: ‘To be honest, they don't understand it, most of them. They don't even know what I'm talking about.’ The method used by Dr Forster and Dr Toth has two parts. One is to draw a tree on the basis of carefully chosen words; the second is to date the splits in the tree by calibrating them with known historical events. This is similar to the way geneticists date their evolutionary trees by tying one or more branch points to known dates from the fossil record.", "html": "<p><b>F</b> Dr Forster said that his estimated date of 3200 BC for the arrival of Celtic speakers in the British Isles is also much earlier than the usual date, 600 BC, posited on the basis of archaeological evidence. Dr Forster and Dr Toth said their method of evaluating groups of languages against each other was similar to historical linguists, many of whom restrict their research to how words in only one single language have changed over time. Asked what linguists thought of his approach he said: ‘To be honest, they don&#x27;t understand it, most of them. They don&#x27;t even know what I&#x27;m talking about.’ The method used by Dr Forster and Dr Toth has two parts. One is to draw a tree on the basis of carefully chosen words; the second is to date the splits in the tree by calibrating them with known historical events. This is similar to the way geneticists date their evolutionary trees by tying one or more branch points to known dates from the fossil record.</p>", "letter": "F", "headingQuestion": null}, {"id": "r2-p7", "text": "G Dr April McMahon, a linguist at the University of Sheffield in England, said that Dr Forster's method ‘seems to me to be a good start’, and that it was reasonable to base a language family tree on just a handful of well-chosen words. She had less confidence in the dating method, she said, because language changes in an irregular way based on social factors like the size of the speaker's group and its degree of contact with others.", "html": "<p><b>G</b> Dr April McMahon, a linguist at the University of Sheffield in England, said that Dr Forster&#x27;s method ‘seems to me to be a good start’, and that it was reasonable to base a language family tree on just a handful of well-chosen words. She had less confidence in the dating method, she said, because language changes in an irregular way based on social factors like the size of the speaker&#x27;s group and its degree of contact with others.</p>", "letter": "G", "headingQuestion": null}], "3": [{"id": "r3-p1", "text": "An American philosopher once said, \"If a man can ... make a better mousetrap than his neighbor ... the world will make a beaten path to his door.\" If only marketing innovation was that simple. In today's marketplace, companies that successfully introduce new products are more likely to flourish than those that don’t. However, businesses spend billions of dollars making better \"mousetraps\" only to find consumers rejecting them. Studies show that new products fail at the staggering rate of between 40% and 90%. In the US packaged goods industry, for example, companies introduce 30,000 new products every year, but 70% to 90% of them stay on store shelves for less than 12 months. According to one study, 47% of the start-up companies that pioneered new products later went out of business altogether.", "html": "<p>An American philosopher once said, &quot;If a man can ... make a better mousetrap than his neighbor ... the world will make a beaten path to his door.&quot; If only marketing innovation was that simple. In today&#x27;s marketplace, companies that successfully introduce new products are more likely to flourish than those that don’t. However, businesses spend billions of dollars making better &quot;mousetraps&quot; only to find consumers rejecting them. Studies show that new products fail at the staggering rate of between 40% and 90%. In the US packaged goods industry, for example, companies introduce 30,000 new products every year, but 70% to 90% of them stay on store shelves for less than 12 months. According to one study, 47% of the start-up companies that pioneered new products later went out of business altogether.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p2", "text": "Experts and novices alike tend to dismiss unsuccessful innovations as bad ideas that were destined to fail. But surely that's too simple an explanation. If these innovations were so misguided, why wasn't it obvious from the outset? Why don't consumers buy. innovative products with distinct advantages over existing ones? To understand why new products fail we must delve into the psychology of behavior change.", "html": "<p>Experts and novices alike tend to dismiss unsuccessful innovations as bad ideas that were destined to fail. But surely that&#x27;s too simple an explanation. If these innovations were so misguided, why wasn&#x27;t it obvious from the outset? Why don&#x27;t consumers buy. innovative products with distinct advantages over existing ones? To understand why new products fail we must delve into the psychology of behavior change.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p3", "text": "Companies have long assumed that they have only to develop innovations that are objectively superior to existing products, and consumers will have sufficient incentive to purchase them. In the 1960s, communications scholar Everett Rogers called the concept \"relative advantage\" and identified it as the most critical driver of new-product adoption. Although compelling, the theory has one major flaw: it fails to capture the psychological biases that affect decision-making. In 2002, psychologist Daniel Kahneman won the Nobel Prize in economics for his research into the reasons why individuals deviate from rational economic behavior. One of the cornerstones of that research, developed with psychologist Amos Tversky, is how individuals value choices in the marketplace. Kahneman and Tversky showed that our responses to the alternatives before us have four distinct characteristics.", "html": "<p>Companies have long assumed that they have only to develop innovations that are objectively superior to existing products, and consumers will have sufficient incentive to purchase them. In the 1960s, communications scholar Everett Rogers called the concept &quot;relative advantage&quot; and identified it as the most critical driver of new-product adoption. Although compelling, the theory has one major flaw: it fails to capture the psychological biases that affect decision-making. In 2002, psychologist Daniel Kahneman won the Nobel Prize in economics for his research into the reasons why individuals deviate from rational economic behavior. One of the cornerstones of that research, developed with psychologist Amos Tversky, is how individuals value choices in the marketplace. Kahneman and Tversky showed that our responses to the alternatives before us have four distinct characteristics.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p4", "text": "First, people evaluate the attractiveness of an alternative based not on its objective or actual value, but on its subjective or perceived value. Second, consumers evaluate new products relative to the products they already own. Third, people view any improvements relative to this reference point and treat all shortcomings as losses. Fourth, and most important, losses have a far greater impact on people than similarly sized gains, a phenomenon that Kahneman and Tversky called \"loss aversion\". Loss aversion leads people to value products they already possess more than those that they don't. In other words, our desire to keep what we have is far greater than our desire to gain something new.", "html": "<p>First, people evaluate the attractiveness of an alternative based not on its objective or actual value, but on its subjective or perceived value. Second, consumers evaluate new products relative to the products they already own. Third, people view any improvements relative to this reference point and treat all shortcomings as losses. Fourth, and most important, losses have a far greater impact on people than similarly sized gains, a phenomenon that Kahneman and Tversky called &quot;loss aversion&quot;. Loss aversion leads people to value products they already possess more than those that they don&#x27;t. In other words, our desire to keep what we have is far greater than our desire to gain something new.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p5", "text": "In a 1990 paper, behavioral economist Richard Thaler and his colleagues described a series of experiments they conducted to quantify this phenomenon. In one experiment, they gave coffee mugs to a group of people, the \"Sellers\", and asked at what price point, from 250 to $9.25, they would be willing to part with those mugs. The researchers then asked another group, the \"Choosers\", to whom they didn't give coffee mugs, to indicate whether they would choose the money or the mug at each price point. In objective terms, all the Sellers and the Choosers were in the same situation: they were choosing between a mug and a sum of money. In one trial the Sellers priced the mug at $7.12, on average, but the Choosers were willing to pay only $3.12. In another trial, the Sellers and the Choosers valued the mug at $7 and $3.50, respectively. Overall, the Sellers always demanded at least twice as much to give up the mugs as the Choosers would pay to obtain them.", "html": "<p>In a 1990 paper, behavioral economist Richard Thaler and his colleagues described a series of experiments they conducted to quantify this phenomenon. In one experiment, they gave coffee mugs to a group of people, the &quot;Sellers&quot;, and asked at what price point, from 250 to $9.25, they would be willing to part with those mugs. The researchers then asked another group, the &quot;Choosers&quot;, to whom they didn&#x27;t give coffee mugs, to indicate whether they would choose the money or the mug at each price point. In objective terms, all the Sellers and the Choosers were in the same situation: they were choosing between a mug and a sum of money. In one trial the Sellers priced the mug at $7.12, on average, but the Choosers were willing to pay only $3.12. In another trial, the Sellers and the Choosers valued the mug at $7 and $3.50, respectively. Overall, the Sellers always demanded at least twice as much to give up the mugs as the Choosers would pay to obtain them.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p6", "text": "In a 1989 paper, economist Jack Knetsch helped to explain why people tend to stick with what they have even if a better alternative exists, by providing a compelling demonstration of what is known as the \"status quo bias\". Knetsch asked one group of students to choose between an attractive coffee mug and a bar of Swiss chocolate. He gave a second group the coffee mugs but later allowed each student to exchange their mugs for a chocolate bar. Finally, Knetsch gave chocolate bars to a third group then later allowed them to exchange their bars for a mug. Of the students initially given a choice, 56% chose the mug and 44% chose the chocolate bar, indicating a near even split in preferences between the two products. Logically, therefore, about half of the students to whom Knetsch gave the coffee mug should have traded for the chocolate bar and vice versa. However, in reality, only 11% of the students with mugs and 10% of those with chocolate bars wanted to exchange their products. To approximately 90% of the students, giving up what they already had seemed like a painful loss and reduced their desire to trade.", "html": "<p>In a 1989 paper, economist Jack Knetsch helped to explain why people tend to stick with what they have even if a better alternative exists, by providing a compelling demonstration of what is known as the &quot;status quo bias&quot;. Knetsch asked one group of students to choose between an attractive coffee mug and a bar of Swiss chocolate. He gave a second group the coffee mugs but later allowed each student to exchange their mugs for a chocolate bar. Finally, Knetsch gave chocolate bars to a third group then later allowed them to exchange their bars for a mug. Of the students initially given a choice, 56% chose the mug and 44% chose the chocolate bar, indicating a near even split in preferences between the two products. Logically, therefore, about half of the students to whom Knetsch gave the coffee mug should have traded for the chocolate bar and vice versa. However, in reality, only 11% of the students with mugs and 10% of those with chocolate bars wanted to exchange their products. To approximately 90% of the students, giving up what they already had seemed like a painful loss and reduced their desire to trade.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p7", "text": "Interestingly, most people seem oblivious to the existence of the behaviors implicit in these biases. In study after study, when researchers presented people with evidence that they had irrationally overvalued what they had, they were shocked, skeptical and more than a little defensive. These behavioral tendencies are universal, but awareness of them is not.", "html": "<p>Interestingly, most people seem oblivious to the existence of the behaviors implicit in these biases. In study after study, when researchers presented people with evidence that they had irrationally overvalued what they had, they were shocked, skeptical and more than a little defensive. These behavioral tendencies are universal, but awareness of them is not.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p8", "text": "In a perfect world, companies would know that consumers irrationally overvalue incumbent products and would take that bias into account when launching innovations. But developers are also biased - in favor of new products. Having worked on a new product for years, developers operate in a world where their innovation is the reference point. They're convinced that the product works and they are keenly aware of the shortcomings of existing alternatives. Companies call those developers \"product champions\" or \"believers\", suggesting that they have embraced a world the rest of us haven't yet.", "html": "<p>In a perfect world, companies would know that consumers irrationally overvalue incumbent products and would take that bias into account when launching innovations. But developers are also biased - in favor of new products. Having worked on a new product for years, developers operate in a world where their innovation is the reference point. They&#x27;re convinced that the product works and they are keenly aware of the shortcomings of existing alternatives. Companies call those developers &quot;product champions&quot; or &quot;believers&quot;, suggesting that they have embraced a world the rest of us haven&#x27;t yet.</p>", "letter": null, "headingQuestion": null}]}, "transcripts": {"1": "<p>Seaweed, a common plant that grows in the sea, has been an important food, fuel, and fertilizer since prehistoric times. For example, it has supplemented the diet of sheep in the Orkneys, islands off the coast of Scotland, since Neolithic times, roughly 5000 years ago. In the early part of the 8th century in Japan, seaweed was already such a key part of people’s regular diet that legislation was introduced giving people the right to pay their taxes to the Emperor in the form of seaweed.</p><p>The oldest evidence of seaweed use was found in South America, dating from 12,500 years ago. The remains of red seaweed mixed with a medicinal herb were discovered on the floor of a medicine hut at Monte Verde, Chile, one of the oldest human habitation sites in the Americas. The Monte Verde findings led to a re-evaluation of the importance of plants to the communities of that region. It was previously believed that their diet was predominantly meat-based, and therefore reliant on the hunting skills of men. However, these findings suggest that women, known to be responsible for the gathering of plants such as seaweed, also played an important pait in the provision of food.</p><p>The first recorded commercial use of seaweed in Europe was in the 17th century in France and Norway. Coastal populations, mainly farmers, gathered and burnt seaweed to produce potash, a substance which is used in the production of glass and soap. In 1800, Norway exported 1500 tonnes of potash.</p><p>Simple seaweed cultivation techniques were first developed in Japan in the mid-17th century and became increasingly popular over the next three centuries. In 1948, however, a series of typhoons combined with increased pollution in coastal waters led to a total collapse in Japanese production of nori, the type of seaweed used to make sushi. And because almost nothing was known about its life cycle, no one could figure out how to grow new plants from scratch to repopulate the depleted seaweed beds. The country’s nori industry ground to a halt, and many farmers lost their livehoods. It was a British scientist, Dr. Kathleen Drew-Baker, who was credited with saving Japan’s seaweed farming industry. Based at Manchester University in the 1940s, she was studying a seaweed called laver, which is the Welsh equivalent of nori. In 1949, she published a paper outlining her discovery that certain tiny algae were actually baby seaweed, rather than an entirely separate species, as had previously been thought. After reading her research, Japanese scientists quickly developed methods for seeding these tiny algae artificially so that new plants could be grown. This made the mass production of nori possible. Although hardly anyone has heard of Dr Drew-Baker in the UK, she is known as the ‘Mother of the Sea’ in Japan, and a statue of her can be found in the Japanese city of Osaka.</p><p>In the United States, Professor Charles Yarish of the University of Connecticut should probably be called the ‘Father of the Sea’ for his work on kelp, a large brown seaweed. The renowned scientist, who has been studying the biology of seaweed since the early 1970s, recently turned his attention to the development of revolutionary techniques for the harvesting of this species. Yarish has helped make it an economically viable crop for the New England fishermen whose livelihoods were threatened by a combination of overfishing, pollution, and warming waters.</p><p>As the world population grows and the climate changes, there is increased interest from businesses and development organizations in the use of seaweed for food and energy. Seaweed, which can grow rapidly and efficiently, provides plant-based proteins, and could also be used as a source of biofuels to replace fossil fuels. Its ability to absorb a number of environmentally unfriendly chemicals discharged by farms, factories and wastewater treatment plants also makes it valuable as a means of reducing pollution.</p><p>Seaweed cultivation in Asia has grown from the late 1950s into an industry offering sustainable employment in developing and emerging economies in many countries, notably Indonesia and China. However, seaweed farming is not very well developed in Europe and the industry still relies on the harvesting, either manually or mechanically, of wild seaweed. The main constraints on the development of seaweed farming in Europe have been the lack of markets and the relative expense of European production compared to Asian production.</p><p>A 2016 report from the World Bank estimates that annual global seaweed production could reach 500 million dry tons by 2050 if the industry is able to increase its harvest by 14% per year. Hitting that 500 million mark would boost the world’s food supply by 10% from the current level, generating 50 million jobs in the process. As a biofuel for vehicles, it could also replace about 1.5% of the fossil fuels used today.</p>", "2": "<p><b>A</b> In November 1897, in a field near the village of Coligny in eastern France, a local inhabitant unearthed two strange objects. One was an imposing statue of Mars, the Roman god of war. The other was an ancient bronze tablet, 1.5 metres wide and 1 metre high. It bore numerals in Roman but the words were in Gaulish, a version of the Celtic language spoken by the inhabitants of France before the Roman conquest in the first century BC. The tablet turned out to be one of the most important sources of words from this extinct language.</p><p><b>B </b>Two researchers, geneticist Dr Peter Forster and linguist Dr Alfred Toth, have now used the calendar and other Celtic inscriptions to reconstruct the history of Celtic and its position in the Indo-European family of languages. They say that Celtic became a language in its own right and entered the British Isles much earlier than supposed. Then in the first century BC, the Romans defeated the Celts, both in France and in Britain, so decisively that their language, Latin, and its successor languages displaced Celtic over much of its former territory. In the British Isles, Celtic speakers survived in two main groups: the Goidelic branch of Celtic, which includes Irish and Scots Gaelic, and the Brythonic branch, formed mainly of Welsh and Breton, a Celtic tongue carried to Brittany in France by emigrants from Cornwall.</p><p><b>C</b> Because languages change so fast, historical linguists have little faith in language trees that go back more than a few thousand years. Dr Forster has developed a new dating method for relating a group of languages, basing it on the tree-drawing techniques used to trace the evolutionary relationships among genes. The method will work on just a handful of words, a fortunate circumstance since only some 30 Gaulish words have known counterparts in all the other languages under study. Dr Forster and Dr Toth have used the method to draw up a tree relating the different branches of Celtic to one another and to other Indo-European languages like English, French, Spanish, Latin and Greek. In a published article, they say that soon after the ancestral Indo-European language arrived in Europe over 5,000 years ago, it split into different branches leading to Celtic, Latin, Greek and English. Within Celtic, their tree shows that Gaulish the mainland European version of the language separated from its Goidelic and Brythonic cousins, much as might be expected from the facts of geography</p><p><b>D</b> The researchers&#x27; method even dates the points at which their language tree divides, although the dates have a wide range of possibility. They calculate that the Indo-European language initially fragmented in Europe around 8100 BC, plus or minus 1,900 years, and the divergence between the mainland European and British versions of Gaelic took place in 3200 BC, plus or minus 1,500 years. These dates are much earlier than previously estimated. ‘The traditional date of the Indo-European fragmentation has been 4000 BC for some time,’ said linguist Dr Merritt Ruhlen. He said the new method ‘seems pretty reasonable’ and should be useful in tracing back the earlier history of the Indo-European language.</p><p><b>E</b> Specialists have long debated which country was the homeland of the Indo-Europeans and whether their language was spread by conquest or because its speakers were the first agriculturists whose methods and tongue were adopted by other populations. The second theory, that it was spread by agriculture, has been advocated by archaeologist Dr Colin Renfrew. Dr Forster, who works with Dr Renfrew, said in an interview that the suggested date 8100 BC for the arrival of Indo-European in Europe does seem to vindicate Renfrew&#x27;s archaeological idea that the Indo-European languages were spread by farmers. Agriculture started to arrive in Europe from the Near East around 6000 BC, which is earlier than the traditional date proposed by linguists for the spread of Indo-European. This writing would fit with the lower end of Dr Forster&#x27;s range of dates.</p><p><b>F</b> Dr Forster said that his estimated date of 3200 BC for the arrival of Celtic speakers in the British Isles is also much earlier than the usual date, 600 BC, posited on the basis of archaeological evidence. Dr Forster and Dr Toth said their method of evaluating groups of languages against each other was similar to historical linguists, many of whom restrict their research to how words in only one single language have changed over time. Asked what linguists thought of his approach he said: ‘To be honest, they don&#x27;t understand it, most of them. They don&#x27;t even know what I&#x27;m talking about.’ The method used by Dr Forster and Dr Toth has two parts. One is to draw a tree on the basis of carefully chosen words; the second is to date the splits in the tree by calibrating them with known historical events. This is similar to the way geneticists date their evolutionary trees by tying one or more branch points to known dates from the fossil record.</p><p><b>G</b> Dr April McMahon, a linguist at the University of Sheffield in England, said that Dr Forster&#x27;s method ‘seems to me to be a good start’, and that it was reasonable to base a language family tree on just a handful of well-chosen words. She had less confidence in the dating method, she said, because language changes in an irregular way based on social factors like the size of the speaker&#x27;s group and its degree of contact with others.</p>", "3": "<p>An American philosopher once said, &quot;If a man can ... make a better mousetrap than his neighbor ... the world will make a beaten path to his door.&quot; If only marketing innovation was that simple. In today&#x27;s marketplace, companies that successfully introduce new products are more likely to flourish than those that don’t. However, businesses spend billions of dollars making better &quot;mousetraps&quot; only to find consumers rejecting them. Studies show that new products fail at the staggering rate of between 40% and 90%. In the US packaged goods industry, for example, companies introduce 30,000 new products every year, but 70% to 90% of them stay on store shelves for less than 12 months. According to one study, 47% of the start-up companies that pioneered new products later went out of business altogether.</p><p>Experts and novices alike tend to dismiss unsuccessful innovations as bad ideas that were destined to fail. But surely that&#x27;s too simple an explanation. If these innovations were so misguided, why wasn&#x27;t it obvious from the outset? Why don&#x27;t consumers buy. innovative products with distinct advantages over existing ones? To understand why new products fail we must delve into the psychology of behavior change.</p><p>Companies have long assumed that they have only to develop innovations that are objectively superior to existing products, and consumers will have sufficient incentive to purchase them. In the 1960s, communications scholar Everett Rogers called the concept &quot;relative advantage&quot; and identified it as the most critical driver of new-product adoption. Although compelling, the theory has one major flaw: it fails to capture the psychological biases that affect decision-making. In 2002, psychologist Daniel Kahneman won the Nobel Prize in economics for his research into the reasons why individuals deviate from rational economic behavior. One of the cornerstones of that research, developed with psychologist Amos Tversky, is how individuals value choices in the marketplace. Kahneman and Tversky showed that our responses to the alternatives before us have four distinct characteristics.</p><p>First, people evaluate the attractiveness of an alternative based not on its objective or actual value, but on its subjective or perceived value. Second, consumers evaluate new products relative to the products they already own. Third, people view any improvements relative to this reference point and treat all shortcomings as losses. Fourth, and most important, losses have a far greater impact on people than similarly sized gains, a phenomenon that Kahneman and Tversky called &quot;loss aversion&quot;. Loss aversion leads people to value products they already possess more than those that they don&#x27;t. In other words, our desire to keep what we have is far greater than our desire to gain something new.</p><p>In a 1990 paper, behavioral economist Richard Thaler and his colleagues described a series of experiments they conducted to quantify this phenomenon. In one experiment, they gave coffee mugs to a group of people, the &quot;Sellers&quot;, and asked at what price point, from 250 to $9.25, they would be willing to part with those mugs. The researchers then asked another group, the &quot;Choosers&quot;, to whom they didn&#x27;t give coffee mugs, to indicate whether they would choose the money or the mug at each price point. In objective terms, all the Sellers and the Choosers were in the same situation: they were choosing between a mug and a sum of money. In one trial the Sellers priced the mug at $7.12, on average, but the Choosers were willing to pay only $3.12. In another trial, the Sellers and the Choosers valued the mug at $7 and $3.50, respectively. Overall, the Sellers always demanded at least twice as much to give up the mugs as the Choosers would pay to obtain them.</p><p>In a 1989 paper, economist Jack Knetsch helped to explain why people tend to stick with what they have even if a better alternative exists, by providing a compelling demonstration of what is known as the &quot;status quo bias&quot;. Knetsch asked one group of students to choose between an attractive coffee mug and a bar of Swiss chocolate. He gave a second group the coffee mugs but later allowed each student to exchange their mugs for a chocolate bar. Finally, Knetsch gave chocolate bars to a third group then later allowed them to exchange their bars for a mug. Of the students initially given a choice, 56% chose the mug and 44% chose the chocolate bar, indicating a near even split in preferences between the two products. Logically, therefore, about half of the students to whom Knetsch gave the coffee mug should have traded for the chocolate bar and vice versa. However, in reality, only 11% of the students with mugs and 10% of those with chocolate bars wanted to exchange their products. To approximately 90% of the students, giving up what they already had seemed like a painful loss and reduced their desire to trade.</p><p>Interestingly, most people seem oblivious to the existence of the behaviors implicit in these biases. In study after study, when researchers presented people with evidence that they had irrationally overvalued what they had, they were shocked, skeptical and more than a little defensive. These behavioral tendencies are universal, but awareness of them is not.</p><p>In a perfect world, companies would know that consumers irrationally overvalue incumbent products and would take that bias into account when launching innovations. But developers are also biased - in favor of new products. Having worked on a new product for years, developers operate in a world where their innovation is the reference point. They&#x27;re convinced that the product works and they are keenly aware of the shortcomings of existing alternatives. Companies call those developers &quot;product champions&quot; or &quot;believers&quot;, suggesting that they have embraced a world the rest of us haven&#x27;t yet.</p>"}, "questionSegments": {"1": ["r1-p1"], "2": ["r1-p1"], "3": ["r1-p2"], "4": ["r1-p3"], "5": ["r1-p4"], "6": ["r1-p4"], "7": ["r1-p4"], "8": ["r1-p5"], "9": ["r1-p5"], "10": ["r1-p6"], "11": ["r1-p7"], "12": ["r1-p8"], "13": ["r1-p8"], "14": ["r2-p5"], "15": ["r2-p1"], "16": ["r2-p7"], "17": ["r2-p2"], "18": ["r2-p3"], "19": ["r2-p6"], "20": ["r2-p7"], "21": ["r2-p2"], "22": ["r2-p5"], "23": ["r2-p1"], "24": ["r2-p2"], "25": ["r2-p4"], "26": ["r2-p7"], "27": ["r3-p1"], "28": ["r3-p2"], "29": ["r3-p4"], "30": ["r3-p5"], "31": ["r3-p6"], "32": ["r3-p6"], "33": ["r3-p3"], "34": ["r3-p3"], "35": ["r3-p4"], "36": ["r3-p3"], "37": ["r3-p4"], "38": ["r3-p8"], "39": ["r3-p8"], "40": ["r3-p8"]}, "headingsBySection": {}, "grading": {"pairs": [], "sets": []}, "groups": [[1, 13], [14, 26], [27, 40]], "questionTypes": {"1": "boolean", "2": "boolean", "3": "boolean", "4": "boolean", "5": "boolean", "6": "gap", "7": "gap", "8": "gap", "9": "gap", "10": "gap", "11": "gap", "12": "gap", "13": "gap", "14": "matching", "15": "matching", "16": "matching", "17": "matching", "18": "matching", "19": "matching", "20": "matching", "21": "matching", "22": "matching", "23": "gap", "24": "gap", "25": "gap", "26": "gap", "27": "single", "28": "single", "29": "single", "30": "single", "31": "single", "32": "single", "33": "matching", "34": "matching", "35": "matching", "36": "boolean", "37": "boolean", "38": "boolean", "39": "boolean", "40": "boolean"}, "sourceAnswerKey": {"1": ["TRUE"], "2": ["FALSE"], "3": ["TRUE"], "4": ["NOT GIVEN"], "5": ["TRUE"], "6": ["typhoons"], "7": ["laver"], "8": ["kelp"], "9": ["fishermen"], "10": ["chemicals"], "11": ["markets"], "12": ["jobs"], "13": ["vehicles"], "14": ["E"], "15": ["A"], "16": ["G"], "17": ["B"], "18": ["C"], "19": ["A"], "20": ["D"], "21": ["A"], "22": ["C"], "23": ["Gaulish"], "24": ["Latin"], "25": ["divergence"], "26": ["irregular"], "27": ["C"], "28": ["D"], "29": ["A"], "30": ["B"], "31": ["B"], "32": ["C"], "33": ["B"], "34": ["A"], "35": ["D"], "36": ["NO"], "37": ["YES"], "38": ["NOT GIVEN"], "39": ["NOT GIVEN"], "40": ["NO"]}, "sourceNotes": [], "hasAnswerKey": true};
